 use tracing_subscriber::EnvFilter;

 const DEFAULT_DAEMON_URL: &str = "http://127.0.0.1:4780";
+const AGENT_EVENTS_PATH: &str = "/v1/agent/events";
+const PROJECTION_EVENTS_PATH: &str = "/v1/agent/projection/events";
