         // GET /v1/events (the CONTROL stream that carries permission_request
         // cards) and answers a prompt by POSTing
@@ -1121,20 +1124,35 @@ async fn proxy_permission_decision(
 /// Reverse-proxy the daemon's SSE event stream. We stream the upstream body
 /// straight through so deltas arrive in real time.
 async fn proxy_events(State(state): State<Arc<AppState>>, req: Request) -> impl IntoResponse {
-    // Preserve ?session_id= query string — scopes SSE to one session per
-    // OCEAN_ECOSYSTEM_CONTRACT.md. Do not strip. The full upstream query is
-    // forwarded verbatim so session_id (and any other params like ?all=1)
-    // reaches the daemon and the stream stays scoped to the caller's session.
-    let q = req
-        .uri()
-        .query()
-        .map(|q| format!("?{q}"))
-        .unwrap_or_default();
-    let url = format!(
-        "{}/v1/agent/events{q}",
-        state.daemon_url.trim_end_matches('/')
-    );
-    match state.http.get(&url).send().await {
+    proxy_agent_sse(&state, AGENT_EVENTS_PATH, req).await
+}
+
+/// Exact session projection journal tail. Query parameters include the opaque
+/// cursor and lease; Last-Event-ID must survive proxying so native EventSource
+/// reconnect resumes from the last frame the browser actually received.
+async fn proxy_projection_events(
+    State(state): State<Arc<AppState>>,
+    req: Request,
+) -> impl IntoResponse {
+    proxy_agent_sse(&state, PROJECTION_EVENTS_PATH, req).await
+}
+
+fn agent_sse_upstream_url(daemon_url: &str, path: &str, query: Option<&str>) -> String {
+    let query = query.map(|query| format!("?{query}")).unwrap_or_default();
+    format!("{}{path}{query}", daemon_url.trim_end_matches('/'))
+}
+
+fn request_last_event_id(req: &Request) -> Option<&str> {
+    req.headers().get("last-event-id")?.to_str().ok()
+}
+
+async fn proxy_agent_sse(state: &AppState, path: &str, req: Request) -> Response {
+    let url = agent_sse_upstream_url(&state.daemon_url, path, req.uri().query());
+    let mut upstream = state.http.get(&url);
+    if let Some(value) = request_last_event_id(&req) {
+        upstream = upstream.header("Last-Event-ID", value);
+    }
+    match upstream.send().await {
         Ok(resp) => sse_stream_response(resp),
         Err(err) => (
             StatusCode::BAD_GATEWAY,
@@ -1271,9 +1289,10 @@ async fn tts(
 #[cfg(test)]
 mod tests {
