-        basic_auth_gate, config_payload, is_hashed_asset, livekit_token_daemon_path,
-        percent_encode_path_segment, sse_no_buffer_headers, wasm_headers, AppState,
-        CALL_PLACE_DAEMON_PATH, WASM_CACHE_CONTROL,
+        agent_sse_upstream_url, basic_auth_gate, config_payload, is_hashed_asset,
+        livekit_token_daemon_path, percent_encode_path_segment, request_last_event_id,
+        sse_no_buffer_headers, wasm_headers, AppState, AGENT_EVENTS_PATH, CALL_PLACE_DAEMON_PATH,
+        PROJECTION_EVENTS_PATH, WASM_CACHE_CONTROL,
     };
     use std::sync::Arc;

@@ -1492,6 +1511,27 @@ mod tests {
         );
     }

+    #[test]
+    fn projection_sse_proxy_preserves_full_query_and_last_event_id() {
+        let query = "session_id=s-1&after_cursor=sp1%3Ae%3Ah%3A7&lease_id=l-1";
+        assert_eq!(
+            agent_sse_upstream_url(
+                "http://127.0.0.1:4780/",
+                PROJECTION_EVENTS_PATH,
+                Some(query),
+            ),
+            format!("http://127.0.0.1:4780{PROJECTION_EVENTS_PATH}?{query}")
+        );
+        let request = Request::builder()
+            .uri(format!("{PROJECTION_EVENTS_PATH}?{query}"))
+            .header("Last-Event-ID", "sp1:e:h:7")
+            .body(Body::empty())
+            .unwrap();
+        assert_eq!(request_last_event_id(&request), Some("sp1:e:h:7"));
+        assert_eq!(AGENT_EVENTS_PATH, "/v1/agent/events");
+        assert_eq!(PROJECTION_EVENTS_PATH, "/v1/agent/projection/events");
+    }
+
