text:
    #[serde(default)]
    pub cwd: String,
    #[serde(default)]
    pub workspace_root: Option<String>,
    #[serde(default)]
    pub owning_project: Option<OwningProjectRef>,
    #[serde(default)]
    pub git_branch: Option<String>,
    #[serde(default)]
    pub turn_count: u32,
    #[serde(default)]
    pub updated_at: String,
}

#[derive(Debug, Clone, Deserialize)]
struct SessionDetailResponse {
    ok: bool,
    #[serde(default)]
    session: Option<SessionDetail>,
    #[serde(default)]
    projection: Option<SessionProjection>,
    #[serde(default)]
    error: Option<String>,
}

#[derive(Debug, Clone, Deserialize)]
struct SessionDetail {
    id: String,
    title: String,
    model: String,
    #[serde(default)]
    workspace_root: Option<String>,
    #[serde(default)]
    cwd: Option<String>,
    #[serde(default)]
    transcript: Vec<SessionTranscriptEntry>,
    /// Per-message tool-call/result context the daemon derives alongside the
    /// transcript. We read it to recover `component_render` props on reconnect:
    /// `ComponentRender` is an SSE-only side-channel event that is never folded
    /// into a transcript text entry, but the assistant tool-call that produced it
    /// IS persisted here with its full `arguments` (id/kind/props). Replaying
    /// those lets rendered components survive a mid-turn SSE reconnect instead of
    /// vanishing (OCEAN-382).
    #[serde(default)]
    tool_context: Vec<SessionToolContext>,
    #[serde(default)]
    pending_permissions: Vec<String>,
    /// Additive feature signal. `None` identifies an old daemon; `Some` with a
    /// temporarily absent projection is retried before legacy fallback.
    #[serde(default)]
    persistence_revision: Option<u64>,
}

#[derive(Debug, Clone, Deserialize)]
struct SessionProjection {
    version: u32,
    cursor: String,
    checkpoint_revision: u64,
    #[serde(default)]
    checkpoint: Option<SessionProjectionCheckpoint>,
    lease_id: String,
    lease_expires_ms: i64,
    #[serde(default)]
    pending_events: Vec<SessionProjectionFrame>,
    #[serde(default)]
    state: SessionProjectionState,
}

#[derive(Debug, Clone, Deserialize)]
struct SessionProjectionFrame {
    cursor: String,
    source: SessionProjectionSource,
    event: Value,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "snake_case")]
enum SessionProjectionSource {
    Agent,
    Control,
    Checkpoint,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(tag = "type", deny_unknown_fields)]
enum SessionProjectionCheckpoint {
    #[serde(rename = "projection_checkpoint")]
    Inline {
        persistence_revision: u64,
        transcript: Vec<SessionTranscriptEntry>,
        tool_context: Vec<SessionToolContext>,
    },
    #[serde(rename = "projection_checkpoint_refetch")]
    Refetch { persistence_revision: u64 },
}

#[derive(Debug, Clone, Default, Deserialize)]
struct SessionProjectionState {
    #[serde(default)]
    active_turn: Option<Value>,
    #[serde(default)]
    last_turn_finished: Option<Value>,
    #[serde(default)]
    model_rerouted: Option<Value>,
    #[serde(default)]
    pending_permissions: Vec<Value>,
    #[serde(default)]
    browser_active: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ProjectionCursor {
    prefix: String,
    seq: u64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CursorTransition {
    Duplicate,
    Next,
    Reset,
}

fn parse_projection_cursor(raw: &str) -> Option<ProjectionCursor> {
    let mut parts = raw.split(':');
    if parts.next()? != "sp1" {
        return None;
    }
    let epoch = parts.next()?;
    let session_hash = parts.next()?;
    let seq = parts.next()?.parse().ok()?;
    let epoch_bytes = epoch.as_bytes();
    let valid_epoch = epoch_bytes.len() == 36
        && epoch_bytes.iter().enumerate().all(|(index, byte)| {
            if matches!(index, 8 | 13 | 18 | 23) {
                *byte == b'-'
            } else {
                byte.is_ascii_hexdigit()
            }
        });
    if parts.next().is_some()
        || !valid_epoch
        || session_hash.len() != 16
        || !session_hash.bytes().all(|byte| byte.is_ascii_hexdigit())
    {
        return None;
    }
    Some(ProjectionCursor {
        prefix: format!("sp1:{epoch}:{session_hash}"),
        seq,
    })
}

fn projection_cursor_transition(current: &str, incoming: &str) -> CursorTransition {
    let (Some(current), Some(incoming)) = (
        parse_projection_cursor(current),
        parse_projection_cursor(incoming),
    ) else {
        return CursorTransition::Reset;
    };
    if current.prefix != incoming.prefix {
        CursorTransition::Reset
    } else if incoming.seq <= current.seq {
        CursorTransition::Duplicate
    } else if incoming.seq == current.seq.saturating_add(1) {
        CursorTransition::Next
    } else {
        CursorTransition::Reset
    }
}

