  3424	    fn restart_projection(&self, id: &str, generation: u64, reason: &str) {
  3425	        if !self.projection_generation_is_current(id, generation) {
  3426	            return;
  3427	        }
  3428	        let attempts = self
  3429	            .projection_restart_count
  3430	            .get_untracked()
  3431	            .saturating_add(1);
  3432	        log::warn!("restarting session projection for {id}: {reason} (attempt {attempts})");
  3433	        let next = generation.wrapping_add(1);
  3434	        self.sse_generation.set(next);
  3435	        self.planner_stream_sources
  3436	            .borrow_mut()
  3437	            .reset(id.to_string(), next);
  3438	        batch(|| {
  3439	            // Folded fields belong to the retired cursor and must not survive a
  3440	            // reset while the replacement snapshot is unavailable.
  3441	            self.streaming.set(false);
  3442	            self.active_turn_id.set(None);
  3443	            self.browser_active.set(false);
  3444	            self.browser_last_action.set(None);
  3445	            self.pending_permissions.set(Vec::new());
  3446	            self.active_decision_token.set(None);
  3447	        });
