  3449	            self.status.set("session projection unavailable".into());
  3450	            self.status_detail.set(Some((
  3451	                "session projection unavailable".into(),
  3452	                reason.into(),
  3453	            )));
  3454	            return;
  3455	        }
  3456	        self.projection_restart_count.set(attempts);
  3457	        self.status.set("resyncing session…".into());
  3458	        self.spawn_projection_sync(id.to_string(), next);
  3459	    }
