  3461	    async fn sync_session_projection(&self, id: String, generation: u64) {
  3462	        const PROJECTION_RETRIES: usize = 4;
  3463	        for attempt in 0..PROJECTION_RETRIES {
  3464	            if !self.projection_generation_is_current(&id, generation) {
  3465	                return;
  3466	            }
  3467	            let url = self.url.get_untracked();
  3468	            let get_url = format!("{}/v1/sessions/{id}", url.trim_end_matches('/'));
  3469	            let fetched = Request::get(&get_url).send().await;
  3470	            if !self.projection_generation_is_current(&id, generation) {
  3471	                return;
  3472	            }
  3473	            let response = match fetched {
  3474	                Ok(response) if response.ok() => {
  3475	                    let decoded = response.json::<SessionDetailResponse>().await;
  3476	                    if !self.projection_generation_is_current(&id, generation) {
  3477	                        return;
  3478	                    }
  3479	                    match decoded {
  3480	                        Ok(response) if response.ok => response,
  3481	                        Ok(response) => {
  3482	                            let error = response.error.unwrap_or_else(|| "unknown error".into());
  3483	                            self.status
  3484	                                .set(format!("session load failed: {}", concise_error(&error)));
  3485	                            return;
  3486	                        }
  3487	                        Err(error) => {
  3488	                            log::warn!("projection snapshot decode failed: {error}");
  3489	                            if attempt + 1 == PROJECTION_RETRIES {
  3490	                                self.status.set("session projection decode failed".into());
  3491	                                return;
  3492	                            }
  3493	                            gloo_timers::future::TimeoutFuture::new(75).await;
  3494	                            continue;
  3495	                        }
  3496	                    }
  3497	                }
  3498	                Ok(response) => {
  3499	                    let text = response.text().await.unwrap_or_default();
  3500	                    if !self.projection_generation_is_current(&id, generation) {
  3501	                        return;
  3502	                    }
  3503	                    self.status
  3504	                        .set(format!("session load failed: {}", concise_error(&text)));
  3505	                    return;
  3506	                }
  3507	                Err(error) => {
  3508	                    if attempt + 1 == PROJECTION_RETRIES {
  3509	                        self.status.set(format!(
  3510	                            "session load failed: {}",
  3511	                            concise_error(&error.to_string())
  3512	                        ));
  3513	                        return;
  3514	                    }
  3515	                    gloo_timers::future::TimeoutFuture::new(75).await;
  3516	                    continue;
  3517	                }
  3518	            };
  3519	            if !self.projection_generation_is_current(&id, generation) {
  3520	                return;
  3521	            }
