  3542	                            // an unbounded generation loop or silently downgrade
  3543	                            // an exact-capable daemon to the legacy race.
  3544	                            self.status.set("session projection invalid".into());
  3545	                            return;
  3546	                        }
  3547	                    }
  3548	                },
  3549	                None if detail.persistence_revision.is_none() => {
