  3589	                self.model.set(Some(detail.model));
  3590	            }
  3591	            self.turns.set(turns);
  3592	            self.pinned_widgets.set(pinned);
  3593	            self.streaming.set(false);
  3594	            self.active_turn_id.set(None);
  3595	            self.browser_active.set(false);
  3596	            self.browser_last_action.set(None);
  3597	            self.pending_permissions.set(Vec::new());
  3598	            self.active_decision_token.set(None);
  3599	        });
  3600	        true
  3601	    }
