  3603	    fn install_projection_snapshot(
  3604	        &self,
  3605	        id: &str,
  3606	        generation: u64,
  3607	        prepared: PreparedProjection,
  3608	    ) -> bool {
  3609	        if !self.projection_generation_is_current(id, generation) {
  3610	            return false;
  3611	        }
  3612	        let active = prepared.active_turn.as_ref().and_then(|event| match event {
  3613	            AgentEvent::TurnStarted { turn_id, model, .. } => {
  3614	                Some((turn_id.clone(), model.clone()))
  3615	            }
  3616	            _ => None,
  3617	        });
  3618	        let terminal_turn_id = prepared
  3619	            .last_turn_finished
  3620	            .as_ref()
  3621	            .and_then(|event| match event {
  3622	                AgentEvent::TurnFinished { turn_id, .. } => Some(turn_id.as_str()),
  3623	                _ => None,
  3624	            });
  3625	        let current_turn_id = active
  3626	            .as_ref()
  3627	            .map(|(turn_id, _)| turn_id.as_str())
  3628	            .or(terminal_turn_id);
  3629	        let rerouted = prepared
  3630	            .model_rerouted
  3631	            .as_ref()
  3632	            .and_then(|event| match event {
  3633	                AgentEvent::ModelRerouted {
  3634	                    turn_id, effective, ..
  3635	                } if Some(turn_id.as_str()) == current_turn_id => Some(effective.clone()),
  3636	                _ => None,
  3637	            });
  3638	        let terminal_status = prepared
  3639	            .last_turn_finished
  3640	            .as_ref()
  3641	            .and_then(|event| match event {
  3642	                AgentEvent::TurnFinished { status, error, .. } if active.is_none() => {
  3643	                    Some(match error {
  3644	                        Some(error) => {
  3645	                            let concise = format!("turn failed: {}", concise_error(error));
  3646	                            (concise.clone(), Some((concise, error.clone())))
  3647	                        }
  3648	                        None if status != "completed" => (format!("turn {status}"), None),
  3649	                        None => ("projection sync".into(), None),
  3650	                    })
  3651	                }
  3652	                _ => None,
  3653	            });
  3654	        let last_stats = prepared
  3655	            .last_turn_finished
  3656	            .as_ref()
  3657	            .and_then(|event| match event {
  3658	                AgentEvent::TurnFinished {
  3659	                    input_tokens,
  3660	                    output_tokens,
  3661	                    cache_read_tokens,
  3662	                    tokens_per_second,
  3663	                    ..
  3664	                } => Some(TokenStats {
  3665	                    input: input_tokens.unwrap_or(0),
  3666	                    output: output_tokens.unwrap_or(0),
  3667	                    cache_read: cache_read_tokens.unwrap_or(0),
  3668	                    tokens_per_second: tokens_per_second.unwrap_or(0.0),
  3669	                }),
  3670	                _ => None,
  3671	            });
  3672	        let root = prepared.detail.workspace_root.or(prepared.detail.cwd);
  3673	        let detail_model = prepared.detail.model;
  3674	        batch(|| {
  3675	            self.session_title.set(prepared.detail.title);
  3676	            if let Some(root) = root.filter(|root| !root.is_empty()) {
  3677	                self.cwd.set(root);
  3678	            }
  3679	            self.turns.set(prepared.turns);
  3680	            self.pinned_widgets.set(prepared.pinned);
  3681	            self.pending_permissions.set(prepared.permissions);
  3682	            // Snapshot permission cards are visibility only; authority belongs
  3683	            // only to a locally submitted turn's secret.
  3684	            self.active_decision_token.set(None);
  3685	            self.browser_active.set(prepared.browser_active);
  3686	            self.active_turn_id
  3687	                .set(active.as_ref().map(|(id, _)| id.clone()));
  3688	            self.streaming.set(active.is_some());
  3689	            self.last_turn_tokens.set(last_stats);
  3690	            if let Some(model) = rerouted
  3691	                .or_else(|| active.and_then(|(_, model)| model))
  3692	                .or_else(|| (!detail_model.is_empty()).then_some(detail_model))
  3693	            {
  3694	                self.model.set(Some(model));
  3695	            }
