  3737	                Ok(source) => source,
  3738	                Err(error) => {
  3739	                    daemon.restart_projection(
  3740	                        &id,
  3741	                        generation,
  3742	                        &format!("tail open failed: {error}"),
  3743	                    );
  3744	                    return;
  3745	                }
  3746	            };
