3542	                            // an unbounded generation loop or silently downgrade
3543	                            // an exact-capable daemon to the legacy race.
3544	                            self.status.set("session projection invalid".into());
3545	                            return;
3546	                        }
3547	                    }
3548	                },
3549	                None if detail.persistence_revision.is_none() => {
3550	                    // Explicit old-daemon path. The complete hydrate precedes
3551	                    // connect(), preserving the legacy best-effort ordering.
3552	                    if !self.install_legacy_snapshot(&id, generation, detail) {
3553	                        return;
3554	                    }
3555	                    self.status.set("legacy sync".into());
3556	                    self.connect();
3557	                    return;
3558	                }
3559	                None => {
3560	                    // A new daemon can transiently expose the revision before
3561	                    // its journal snapshot is ready. It must never silently
3562	                    // downgrade to the legacy snapshot/live race.
3563	                    if attempt + 1 == PROJECTION_RETRIES {
3564	                        self.status.set("session projection unavailable".into());
3565	                        return;
3566	                    }
3567	                }
3568	            }
3569	            gloo_timers::future::TimeoutFuture::new(75).await;
3570	        }
3571	    }
