3712	    fn connect_projection_tail(
3713	        &self,
3714	        id: String,
3715	        generation: u64,
3716	        initial_cursor: String,
3717	        lease_id: String,
3718	    ) {
3719	        let daemon = self.clone();
3720	        spawn_local(async move {
3721	            if !daemon.projection_generation_is_current(&id, generation) {
3722	                return;
3723	            }
3724	            let encode = |value: &str| {
3725	                js_sys::encode_uri_component(value)
3726	                    .as_string()
3727	                    .unwrap_or_else(|| value.to_string())
3728	            };
3729	            let events_url = format!(
3730	                "{}/v1/agent/projection/events?session_id={}&after_cursor={}&lease_id={}",
3731	                daemon.url.get_untracked().trim_end_matches('/'),
3732	                encode(&id),
3733	                encode(&initial_cursor),
3734	                encode(&lease_id),
3735	            );
3736	            let mut source = match EventSource::new(&events_url) {
3737	                Ok(source) => source,
3738	                Err(error) => {
3739	                    daemon.restart_projection(
3740	                        &id,
3741	                        generation,
3742	                        &format!("tail open failed: {error}"),
3743	                    );
3744	                    return;
3745	                }
3746	            };
3747	            let projection_events = match source.subscribe("session_projection") {
3748	                Ok(stream) => stream,
3749	                Err(error) => {
3750	                    daemon.restart_projection(
3751	                        &id,
3752	                        generation,
3753	                        &format!("tail subscribe failed: {error}"),
3754	                    );
3755	                    return;
3756	                }
3757	            };
3758	            let projection_resets = match source.subscribe("projection_reset") {
3759	                Ok(stream) => stream,
3760	                Err(error) => {
3761	                    daemon.restart_projection(
3762	                        &id,
3763	                        generation,
3764	                        &format!("reset subscribe failed: {error}"),
3765	                    );
3766	                    return;
3767	                }
3768	            };
3769	            // Store while CONNECTING. The browser owns reconnect and sends its
3770	            // Last-Event-ID; replacing this generation explicitly closes it.
3771	            {
3772	                let mut sources = daemon.planner_stream_sources.borrow_mut();
3773	                if sources.session_id != id || sources.generation != generation {
3774	                    return;
3775	                }
3776	                sources.projection = Some(source.clone());
3777	            }
3778	            let mut cursor = initial_cursor;
3779	            let mut stream = futures_util::stream::select(projection_events, projection_resets);
3780	            while let Some(message) = stream.next().await {
3781	                if !daemon.projection_generation_is_current(&id, generation) {
3782	                    return;
3783	                }
3784	                let Ok((event_name, message)) = message else {
3785	                    // gloo-net suppresses transient CONNECTING errors; an error
3786	                    // delivered here is terminal, so a new GET/lease is needed.
3787	                    daemon.restart_projection(&id, generation, "projection tail closed");
3788	                    return;
3789	                };
3790	                if event_name == "projection_reset" {
3791	                    daemon.restart_projection(&id, generation, "daemon projection reset");
3792	                    return;
3793	                }
3794	                let Some(data) = message.data().as_string() else {
3795	                    daemon.restart_projection(&id, generation, "projection frame missing data");
3796	                    return;
3797	                };
3798	                let frame = match serde_json::from_str::<SessionProjectionFrame>(&data) {
3799	                    Ok(frame) => frame,
3800	                    Err(_) => {
3801	                        daemon.restart_projection(
3802	                            &id,
3803	                            generation,
3804	                            "projection frame decode mismatch",
3805	                        );
3806	                        return;
3807	                    }
3808	                };
3809	                if message.last_event_id() != frame.cursor {
3810	                    daemon.restart_projection(
3811	                        &id,
3812	                        generation,
3813	                        "projection SSE id/body cursor mismatch",
3814	                    );
