3816	                }
3817	                match projection_cursor_transition(&cursor, &frame.cursor) {
3818	                    CursorTransition::Duplicate => continue,
3819	                    CursorTransition::Reset => {
3820	                        daemon.restart_projection(
3821	                            &id,
3822	                            generation,
3823	                            "projection cursor gap or prefix change",
3824	                        );
3825	                        return;
3826	                    }
3827	                    CursorTransition::Next => {}
3828	                }
3829	                match frame.source {
3830	                    SessionProjectionSource::Agent => {
3831	                        let event = match serde_json::from_value::<AgentEvent>(frame.event) {
3832	                            Ok(event) if event.session_id() == Some(id.as_str()) => event,
3833	                            _ => {
3834	                                daemon.restart_projection(
3835	                                    &id,
3836	                                    generation,
3837	                                    "agent frame session/decode mismatch",
3838	                                );
3839	                                return;
3840	                            }
3841	                        };
3842	                        apply_event(
3843	                            &event,
3844	                            daemon.turns,
3845	                            daemon.session_id,
3846	                            daemon.streaming,
3847	                            daemon.status,
3848	                            daemon.status_detail,
3849	                            daemon.last_turn_tokens,
3850	                            daemon.session_tokens,
3851	                            daemon.model,
3852	                            daemon.active_turn_id,
3853	                            daemon.browser_active,
3854	                            daemon.browser_last_action,
3855	                            daemon.canvas_patches,
