3881	                            frame.event,
3882	                        ) {
3883	                            Ok(checkpoint) => checkpoint,
3884	                            Err(_) => {
3885	                                daemon.restart_projection(
3886	                                    &id,
3887	                                    generation,
3888	                                    "checkpoint decode mismatch",
3889	                                );
3890	                                return;
3891	                            }
3892	                        };
