5599	fn component_replay_matches(
5600	    tool_context: &[SessionToolContext],
5601	) -> std::collections::HashMap<(String, usize), &SessionToolContext> {
5602	    // Tool call ids should be unique, but malformed persisted history must not
5603	    // let a duplicate select an arbitrary call. `None` marks an ambiguous id.
5604	    let mut pending: std::collections::HashMap<&str, Option<&SessionToolContext>> =
5605	        std::collections::HashMap::new();
5606	    let mut result_ordinals: std::collections::HashMap<&str, usize> =
5607	        std::collections::HashMap::new();
5608	    let mut matched = std::collections::HashMap::new();
5609	
5610	    for entry in tool_context {
5611	        match entry.kind.as_str() {
5612	            "call" => {
5613	                let id = entry.tool_call_id.as_str();
5614	                if entry.tool_name == "component_render" || entry.tool_name == "component_unmount" {
5615	                    pending
5616	                        .entry(id)
5617	                        .and_modify(|candidate| *candidate = None)
5618	                        .or_insert(Some(entry));
5619	                } else if pending.contains_key(id) {
5620	                    pending.insert(id, None);
5621	                }
5622	            }
5623	            "result" => {
5624	                let id = entry.tool_call_id.as_str();
5625	                let ordinal = result_ordinals.entry(id).or_default();
5626	                *ordinal += 1;
5627	                if let Some(Some(call)) = pending.remove(id) {
5628	                    // The protocol requires explicit success. Missing/failed,
5629	                    // result-before-call, duplicate-call, and repeated-result
5630	                    // records have no component effect.
5631	                    if entry.is_error == Some(false) {
5632	                        matched.insert((id.to_string(), *ordinal), call);
5633	                    }
5634	                }
5635	            }
5636	            _ => {}
5637	        }
5638	    }
5639	    matched
5640	}
