5642	fn turns_from_session_transcript(
5643	    entries: Vec<SessionTranscriptEntry>,
5644	    tool_context: &[SessionToolContext],
5645	) -> (Vec<Turn>, Vec<PinnedWidget>) {
5646	    // Derive component effects from the ordered tool-context call/result rail.
5647	    // Transcript result entries provide the point at which each proven effect
5648	    // is inserted into the display-ready turn sequence.
5649	    let component_matches = component_replay_matches(tool_context);
5650	    let mut transcript_result_ordinals: std::collections::HashMap<String, usize> =
5651	        std::collections::HashMap::new();
5652	    let mut turns = Vec::new();
5653	    let mut pinned: Vec<PinnedWidget> = Vec::new();
