 344	    fn append(
 345	        &self,
 440	        &self,
 441	        session_id: &str,
 442	        file_revision: u64,
 443	        file_snapshot: Value,
 444	    ) -> std::result::Result<SessionProjection, ProjectionReset> {
 445	        if self.is_faulted(session_id) {
 446	            return Err(ProjectionReset::Faulted);
 447	        }
 448	
 449	        // Inspect alignment first. A missing/older idle row is repaired only by
 450	        // appending the same visible replacement frame live clients consume —
 451	        // never by silently advancing checkpoint_seq over unrepresented rows.
 452	        let needs_checkpoint = {
 453	            let db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
 454	            match load_row(&db, &self.epoch, session_id).map_err(|_| ProjectionReset::Faulted)? {
 455	                None => true,
 456	                Some(row) => {
 457	                    let state: FoldedState = serde_json::from_str(&row.state_json)
 458	                        .map_err(|_| ProjectionReset::Faulted)?;
 459	                    if file_revision < row.checkpoint_revision
 460	                        || (file_revision > row.checkpoint_revision && state.active_turn.is_some())
 461	                    {
 462	                        return Err(ProjectionReset::RevisionMismatch);
 463	                    }
 464	                    file_revision > row.checkpoint_revision || row.checkpoint_json.is_none()
 465	                }
 466	            }
 467	        };
 468	        if needs_checkpoint {
 469	            self.checkpoint(session_id, file_revision, file_snapshot)
 470	                .map_err(|_| ProjectionReset::Faulted)?;
 471	        }
 472	
 473	        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
 474	        let tx = db.transaction().map_err(|_| ProjectionReset::Faulted)?;
 475	        let row = load_row(&tx, &self.epoch, session_id)
 476	            .map_err(|_| ProjectionReset::Faulted)?
 477	            .ok_or(ProjectionReset::Faulted)?;
 478	        if row.checkpoint_revision != file_revision {
 479	            return Err(ProjectionReset::RevisionMismatch);
 480	        }
 481	        let state: FoldedState =
 482	            serde_json::from_str(&row.state_json).map_err(|_| ProjectionReset::Faulted)?;
 483	        let checkpoint = row
 484	            .checkpoint_json
 485	            .as_deref()
 486	            .map(serde_json::from_str::<SessionProjectionCheckpoint>)
 487	            .transpose()
 488	            .map_err(|_| ProjectionReset::Faulted)?;
 489	        let pending = query_frames(&tx, &self.epoch, session_id, row.checkpoint_seq, row.latest)
 490	            .map_err(|_| ProjectionReset::Faulted)?;
 491	        tx.commit().map_err(|_| ProjectionReset::Faulted)?;
 492	        drop(db);
 493	        let lease = self.issue_lease(session_id, row.latest);
 494	        Ok(SessionProjection {
 495	            version: 1,
 496	            cursor: ProjectionCursor::new(&self.epoch, session_id, row.latest).to_string(),
 497	            checkpoint_revision: row.checkpoint_revision,
 498	            checkpoint,
 499	            lease_id: lease.0,
 500	            lease_expires_ms: lease.1,
 501	            pending_events: pending,
 502	            state: state.wire(),
 503	        })
 504	    }
