 506	    /// Validate and acknowledge only the cursor supplied by a new HTTP request.
 507	    /// Internal SQLite pages must never call this: bytes queued to an SSE channel
 508	    /// are not proof that the client received them.
 509	    pub(crate) fn begin_tail_request(
 510	        &self,
 511	        session_id: &str,
 512	        raw_cursor: &str,
 513	        lease_id: &str,
 514	    ) -> std::result::Result<(), ProjectionReset> {
 515	        let cursor = self.validate_cursor_identity(session_id, raw_cursor)?;
 516	        self.validate_lease(session_id, lease_id, cursor.seq)?;
 517	        self.validate_cursor_position(session_id, cursor.seq)?;
 518	        self.acknowledge_lease(lease_id, cursor.seq)
 519	    }
 520	
 521	    pub(crate) fn page_after(
 522	        &self,
 523	        session_id: &str,
 524	        raw_cursor: &str,
 525	        lease_id: &str,
 526	    ) -> std::result::Result<Vec<SessionProjectionFrame>, ProjectionReset> {
 527	        let cursor = self.validate_cursor_identity(session_id, raw_cursor)?;
 528	        self.validate_lease(session_id, lease_id, cursor.seq)?;
 529	        let db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
 530	        let Some(row) =
 531	            load_row(&db, &self.epoch, session_id).map_err(|_| ProjectionReset::Faulted)?
 532	        else {
 533	            if cursor.seq == 0 {
 534	                return Ok(Vec::new());
 535	            }
 536	            return Err(ProjectionReset::Future);
 537	        };
 538	        if cursor.seq > row.latest {
 539	            return Err(ProjectionReset::Future);
 540	        }
 541	        let earliest: Option<u64> = db
 542	            .query_row(
 543	                "SELECT MIN(seq) FROM session_projection_events WHERE epoch=?1 AND session_id=?2",
 544	                params![&*self.epoch, session_id],
 545	                |row| row.get(0),
 546	            )
 547	            .optional()
 548	            .map_err(|_| ProjectionReset::Faulted)?
 549	            .flatten();
 550	        if cursor.seq < row.latest
 551	            && earliest.is_none_or(|first| cursor.seq.saturating_add(1) < first)
 552	        {
 553	            return Err(ProjectionReset::Retention);
 554	        }
 555	        let through = cursor.seq.saturating_add(PAGE_LIMIT as u64);
 556	        let frames = query_frames(
 557	            &db,
 558	            &self.epoch,
 559	            session_id,
 560	            cursor.seq,
 561	            through.min(row.latest),
 562	        )
 563	        .map_err(|_| ProjectionReset::Faulted)?;
 564	        drop(db);
 565	        // Fetching or queueing a page is not an acknowledgement. Only renew the
 566	        // expiry; min_seq remains the cursor from begin_tail_request.
 567	        self.renew_lease_expiry(lease_id)?;
 568	        Ok(frames)
 569	    }
