 506	    /// Validate and acknowledge only the cursor supplied by a new HTTP request.
 507	    /// Internal SQLite pages must never call this: bytes queued to an SSE channel
 508	    /// are not proof that the client received them.
 509	    pub(crate) fn begin_tail_request(
 510	        &self,
 511	        session_id: &str,
 512	        raw_cursor: &str,
 513	        lease_id: &str,
 514	    ) -> std::result::Result<(), ProjectionReset> {
 515	        let cursor = self.validate_cursor_identity(session_id, raw_cursor)?;
 516	        self.validate_lease(session_id, lease_id, cursor.seq)?;
 517	        self.validate_cursor_position(session_id, cursor.seq)?;
 518	        self.acknowledge_lease(lease_id, cursor.seq)
 519	    }
